class Solution { fun findRedundantDirectedConnection(edges:Array<IntArray>):IntArray{val n=edges.size;val parent=IntArray(n+1);var first=-1;var second=-1;for(i in edges.indices){val from=edges[i][0];val to=edges[i][1];if(parent[to]==0)parent[to]=from else{first=(0 until i).first{edges[it][0]==parent[to]&&edges[it][1]==to};second=i;break}};val union=IntArray(n+1){it};fun find(value:Int):Int{if(union[value]!=value)union[value]=find(union[value]);return union[value]};for(i in edges.indices){if(i==second)continue;val a=find(edges[i][0]);val b=find(edges[i][1]);if(a==b)return if(first>=0)edges[first] else edges[i];union[b]=a};return edges[second]} }
